interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
}

function paginate<T extends { id: string }>(all: readonly T[], limit: number, after: string | null = null): Page<T> {
  const index = after === null ? -1 : all.findIndex((item) => item.id === after);
  const items = all.slice(index + 1, index + 1 + limit);
  const last = items.at(-1);
  return { items, nextCursor: index + 1 + limit < all.length && last ? last.id : null };
}

const txs = [{ id: "T1" }, { id: "T2" }, { id: "T3" }];
