const p2 = paginate(txs, 2, p1.nextCursor);
console.log(p1.items.length, p1.nextCursor, p2.items.map((t) => t.id), p2.nextCursor);

class TtlCache<K, V extends {} | null> {
  private readonly entries = new Map<K, { value: V; expiresAt: number }>();
  constructor(private readonly ttlMs: number, private readonly now: () => number) {}

  async getOrLoad(key: K, load: (key: K) => Promise<V>): Promise<V> {
    const entry = this.entries.get(key);
    if (entry !== undefined && entry.expiresAt > this.now()) return entry.value;
    const value = await load(key);
    this.entries.set(key, { value, expiresAt: this.now() + this.ttlMs });
    return value;
  }
}

let clock = 0;
let calls = 0;
const rates = new TtlCache<string, number>(1000, () => clock);
const load = async () => ++calls * 100;

const a = await rates.getOrLoad("USD/NGN", load);
clock = 500;
const b = await rates.getOrLoad("USD/NGN", load);
clock = 1500;
const c = await rates.getOrLoad("USD/NGN", load);
console.log(a, b, c, calls);

