type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function all<T, E>(results: readonly Result<T, E>[]): Result<T[], E> {
  const values: T[] = [];
  for (const result of results) {
    if (!result.ok) return result;
    values.push(result.value);
  }
  return { ok: true, value: values };
}

const check = (kobo: number): Result<number, "invalid-amount"> =>
  kobo > 0 ? { ok: true, value: kobo } : { ok: false, error: "invalid-amount" };

console.log(all([5000, 1200].map(check)));
console.log(all([5000, -1, 0].map(check)));
